def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color in (0,6) or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            # Restore the rectangular colored object across occluding noise and holes.
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    if grid[y][x] in (color,6): out[y][x]=color
    for r in range(h):
        for c in range(w):
            if grid[r][c]==6 and out[r][c]==6: out[r][c]=0
    return out
